<?php
if (!defined('ABSPATH')) exit;
function gim_cancel_job($job_id,$customer_id,$reason=''){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Forbidden.'); if(in_array($job->status,['in_progress','provider_completed','completed'],true))return new WP_Error('started','Work has started; use the dispute process.'); $payments=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".gim_table('payments')." WHERE job_id=%d AND status IN ('captured','partially_refunded')",$job_id)); $refund=0;$retained=0; $estimate=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".gim_table('estimates')." WHERE job_id=%d AND status='accepted' ORDER BY id DESC LIMIT 1",$job_id)); $late=false; if($job->scheduled_at)$late=(strtotime($job->scheduled_at)-time())<=DAY_IN_SECONDS; if($late&&$estimate){ foreach(gim_decode($estimate->items_json) as $i){ if($i['type']==='callout'||($i['type']==='emergency'&&$job->urgency==='emergency'))$retained+=(int)$i['line_pence']; } }
 foreach($payments as $p){$remaining=(int)$p->amount_pence-(int)$p->refunded_pence; $take=max(0,min($remaining,$remaining-$retained)); if($take>0){$r=gim_refund_payment($p->id,$take); if(is_wp_error($r))return $r; $refund+=$take; $retained=max(0,$retained-($remaining-$take));}}
 $ref=gim_ref('GM-CAN'); $wpdb->insert(gim_table('cancellations'),['reference'=>$ref,'job_id'=>$job_id,'customer_id'=>$customer_id,'status'=>'settled','reason'=>sanitize_textarea_field($reason),'refund_pence'=>$refund,'retained_pence'=>$retained,'policy_json'=>gim_json(['late'=>$late,'rule'=>'prework-v1']),'created_at'=>gim_now(),'updated_at'=>gim_now()]); $wpdb->update(gim_table('jobs'),['status'=>'cancelled','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('job.cancelled','job',$job->reference,['refund_pence'=>$refund]); return ['refund_pence'=>$refund,'retained_pence'=>$retained]; }
function gim_open_dispute($job_id,$customer_id,$reason){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Only the customer can open this dispute.'); $open=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('disputes')." WHERE job_id=%d AND status NOT IN ('resolved','closed')",$job_id)); if($open)return new WP_Error('open','An active dispute already exists.'); $ref=gim_ref('GM-DSP'); $wpdb->insert(gim_table('disputes'),['reference'=>$ref,'job_id'=>$job_id,'customer_id'=>$customer_id,'provider_id'=>$job->provider_id,'status'=>'open','reason'=>sanitize_textarea_field($reason),'created_at'=>gim_now(),'updated_at'=>gim_now()]); gim_audit('dispute.opened','dispute',$ref); return $wpdb->insert_id; }
function gim_provider_respond_dispute($id,$provider_user_id,$response){ global $wpdb; $d=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('disputes').' WHERE id=%d',$id)); $p=gim_provider_profile($provider_user_id); if(!$d||!$p||(int)$d->provider_id!==(int)$p->id)return new WP_Error('forbidden','Forbidden.'); $wpdb->update(gim_table('disputes'),['provider_response'=>sanitize_textarea_field($response),'status'=>'under_review','updated_at'=>gim_now()],['id'=>$id]); return true; }
function gim_admin_resolve_dispute($id,$resolution,$refund_pence=0,$notes=''){ global $wpdb; if(!current_user_can('gim_manage_disputes')&&!current_user_can('manage_options'))return new WP_Error('forbidden','Forbidden.'); $d=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('disputes').' WHERE id=%d',$id)); if(!$d)return new WP_Error('missing','Dispute not found.'); $allowed=['FULL_REFUND','PARTIAL_REFUND','RELEASE_PAYMENT','PARTIAL_RELEASE','NO_FINANCIAL_ADJUSTMENT','OTHER']; if(!in_array($resolution,$allowed,true))return new WP_Error('resolution','Invalid resolution.'); if(in_array($resolution,['FULL_REFUND','PARTIAL_REFUND'],true)){ $remaining=$refund_pence; $payments=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".gim_table('payments')." WHERE job_id=%d AND status IN ('captured','partially_refunded') ORDER BY id DESC",$d->job_id)); if($resolution==='FULL_REFUND')$remaining=array_sum(array_map(fn($p)=>(int)$p->amount_pence-(int)$p->refunded_pence,$payments)); foreach($payments as $p){if($remaining<=0)break;$amt=min($remaining,(int)$p->amount_pence-(int)$p->refunded_pence); if($amt>0){$r=gim_refund_payment($p->id,$amt);if(is_wp_error($r))return $r;$remaining-=$amt;}} if($remaining>0)return new WP_Error('refund','Refund exceeds refundable funds.'); }
 $wpdb->update(gim_table('disputes'),['status'=>'resolved','resolution'=>$resolution,'refund_pence'=>(int)$refund_pence,'admin_notes'=>sanitize_textarea_field($notes),'updated_at'=>gim_now()],['id'=>$id]); gim_audit('dispute.resolved','dispute',$d->reference,['resolution'=>$resolution]); return true; }
